/* live layer — only active when html.live is set by live.js */
.live .lv-r{opacity:0;transform:translate3d(0,22px,0);transition:opacity .7s ease,transform .75s cubic-bezier(.2,.8,.2,1);transition-delay:var(--d,0ms)}
.live .lv-r.lv-in{opacity:1;transform:none}
.live .lv-lift{transition:transform .28s cubic-bezier(.2,.8,.2,1),box-shadow .28s ease}
.live .lv-lift:hover,.live .lv-lift:active{transform:translateY(-5px);box-shadow:0 18px 30px -18px rgba(0,0,0,.35)}
.live .lv-mag,.live .lv-tilt{transition:transform .18s ease-out;will-change:transform}
.live .lv-tilt{transform-style:preserve-3d}
.lv-bar{position:fixed;left:0;top:0;height:3px;width:100%;background:var(--c-accent,#e8590c);transform:scaleX(0);transform-origin:0 50%;z-index:9999;pointer-events:none}
.live .lv-w{display:inline-block;opacity:0;transform:translate3d(0,.5em,0);animation:lvw .7s cubic-bezier(.2,.8,.2,1) forwards;animation-delay:calc(var(--i)*70ms + 120ms)}
@keyframes lvw{to{opacity:1;transform:none}}
.lv-ring{position:fixed;left:-18px;top:-18px;width:36px;height:36px;border-radius:50%;border:2px solid var(--c-accent,#e8590c);pointer-events:none;z-index:9999;transition:width .2s,height .2s,margin .2s,background .2s;mix-blend-mode:difference}
.lv-ring.lv-hov{width:60px;height:60px;margin:-12px 0 0 -12px;background:color-mix(in srgb,var(--c-accent,#e8590c) 25%,transparent)}
@media(prefers-reduced-motion:reduce){.live .lv-r{opacity:1;transform:none;transition:none}.live .lv-w{opacity:1;transform:none;animation:none}}
